#pragma once

#include "CoreMinimal.h"

class UCanvas;
class UFont;
class UTexture2D;

// A LyShine screen element (layout generated by tools/ui_build_hud.py from the game's screens).
struct FNWUIElement
{
	FString Name;
	FString Path;
	int32 Parent = -1;
	FVector4f Anchors = FVector4f(0, 0, 1, 1);   // left, top, right, bottom (fraction of the parent)
	FVector4f Offsets = FVector4f(0, 0, 0, 0);   // in reference-screen units
	FVector2f Pivot = FVector2f(0.5f, 0.5f);
	FVector2f Scale = FVector2f(1.f, 1.f);
	float Fade = 1.f;
	bool bEnabled = true;
	// Mask (UiMaskComponent): clips the subtree (up to EndIndex); its image only shows with bMaskDraw.
	bool bMask = false;
	bool bMaskDraw = false;
	int32 EndIndex = -1;

	bool bHasImage = false;
	FString Texture;              // game path (lyshineui/images/...dds)
	FLinearColor Color = FLinearColor::White;
	uint8 ImageType = 0;          // 0 stretched, 1 9-slice, ...
	uint8 Blend = 0;              // 0 normal, 1 additive
	uint8 FillType = 0;           // 0 none, 1 linear, 2 radial
	float FillAmount = 1.f;
	float FillStartAngle = 0.f;
	bool bFillClockwise = true;
	int32 FillEdgeOrigin = 0;     // 0 left, 1 top, 2 right, 3 bottom
	bool bHasBorders = false;
	FVector4f Borders = FVector4f(0, 1, 0, 1);   // 9-slice lines: left, right, top, bottom (fractions)

	bool bHasText = false;
	FString Text;
	int32 FontStyle = 0;          // 0 regular, 1 semibold, 2 bold, 3 Pica, 4 Pica italic, 5 Caslon (GameFont)
	float CharSpacing = 0.f;      // LyShine characterspacing (thousandths of the font size)
	int32 CaseOverride = 0;       // LyShine caseoverride: 0 none, 1 lowercase, 2 uppercase
	FString FontFile;             // canvas font (lyshineui/fonts/<name>.font), for bExactText mode
	bool bWrap = false;           // wraptextsetting
	float LineSpacing = 0.f;      // linespacing (reference-screen pixels)
	int32 ShrinkToFit = 0;        // 0 no, 1 uniform, 2 width only
	float MinShrink = 0.f;
	bool bFitWidth = false;       // horizontal UiLayoutFitter: width = the text's (bExactText mode)
	float FontSize = 16.f;
	FLinearColor TextColor = FLinearColor::White;
	int32 HAlign = 0;             // 0 left, 1 center, 2 right
	int32 VAlign = 0;

	// Game state (set by the HUD; empty = layout value).
	TOptional<bool> Visible;
	TOptional<float> Fill;
	TOptional<FLinearColor> Tint;
	TOptional<FString> TextOverride;
	FString TextureOverride;
	float AlphaMul = 1.f;
	// Offset in reference-screen units (e.g. tree nodes spread down the column).
	FVector2f Translate = FVector2f(0.f, 0.f);

	UTexture2D* CachedTexture = nullptr;   // kept alive by the HUD
	FString CachedFor;
};

struct FNWUICanvasLayout
{
	FString Name;
	FVector2f Size = FVector2f(1920.f, 1080.f);
	TArray<FNWUIElement> Elements;
	// Last draw (screen pixels): rectangle, clip and visibility of each element, for clicks.
	TArray<FBox2f> LastRects;
	TArray<FBox2f> LastClips;
	TArray<bool> LastShown;
};

/**
 * Draws game screens on the Unreal Canvas with LyShine layout rules: each element's rectangle
 * = parent rectangle + anchors + offsets, on the reference screen (1920x1080) scaled by height.
 */
class NWPORT_API FNWUILayout
{
public:
	bool Load(const FString& JsonFile);
	bool IsLoaded() const { return Canvases.Num() > 0; }

	// Elements whose path ends with the suffix (e.g. "WeaponAbilitySet/WeaponAbility2/AbilityIcon").
	TArray<FNWUIElement*> Find(const FString& Canvas, const FString& PathSuffix);
	FNWUIElement* FindOne(const FString& Canvas, const FString& PathSuffix);

	// Resolves a game texture -> imported asset (/Game/NW/UI/...); the HUD keeps the reference.
	TFunction<UTexture2D*(const FString&)> ResolveTexture;
	/** LyShine-faithful text (area 4 screens): size = line height in pixels (measured on the font itself), exact family (Nimbus medium and italic), line wrapping, line spacing and shrink to fit.
	 *  When off, the text comes out ~1.56× larger and on a single line (older screens were tuned that way). */
	bool bExactText = false;
	/** LyShine-exact scale: an element's Scale also scales its whole subtree (position, size and text) around its pivot.
	 *  Off: the scale only resizes the element's own rectangle (older screens were tuned that way). */
	bool bScaleChildren = false;
	UFont* Fonts[3] = {nullptr, nullptr, nullptr};

	void Draw(UCanvas* Canvas);
	// Only one canvas (e.g. the same text field drawn at several positions with Translate).
	void DrawOne(UCanvas* Canvas, const FString& CanvasName);
	/**
	 * List: redraws the subtree of element Root (the game's template item, hidden in the normal draw) offset by
	 * Offset (reference-screen units), inside the parent and the clip of the last Draw. Before calling, the screen
	 * fills the subtree's elements (TextOverride, Visible...). Returns the row rectangle in pixels.
	 */
	FBox2f DrawSubtree(UCanvas* Canvas, const FString& CanvasName, const FNWUIElement* Root, const FVector2f& Offset);
	/** Index of the element in the canvas (for DrawSubtree and children) or INDEX_NONE. */
	int32 IndexOf(const FString& CanvasName, const FNWUIElement* Element) const;
	// Frontmost visible element under the point (pixels), in the last draw; Accept filters candidates.
	int32 HitTest(const FString& Canvas, const FVector2D& Point, TFunctionRef<bool(const FNWUIElement&)> Accept) const;
	const FNWUIElement* Element(const FString& Canvas, int32 Index) const;
	FBox2f LastRect(const FString& Canvas, int32 Index) const;
	// Rectangle (pixels) of the element in the last draw; invalid if not drawn.
	FBox2f RectOf(const FNWUIElement* Element) const;
	// Element drawn (visible, with the whole parent chain) in the last draw.
	bool WasShown(const FNWUIElement* Element) const;

	static FString AssetPathFor(const FString& GameTexture);
	// Game font (.otf/.ttf in Data/UI/Fonts) created once and kept alive: 0 Nimbus regular, 1 semibold, 2 bold,
	// 3 Pica (IM Fell, titles), 4 Pica italic, 5 Caslon, 6 Nimbus italic, 7 Nimbus medium.
	static UFont* GameFont(int32 Style);
	/** Log of the elements whose path contains Filter: rectangle and state in the last draw (offline capture). */
	void Dump(const FString& Filter) const;
	/** Text width on the reference screen (widest line), for UiLayoutFitter and layouts built in C++. */
	float TextWidth(UCanvas* Canvas, const FNWUIElement& E, float UIScale) const;
	// Texture imported from the game UI (kept alive).
	static UTexture2D* GameTexture(const FString& GameTexturePath);

private:
	void DrawCanvas(UCanvas* Canvas, FNWUICanvasLayout& Layout);
	void DrawImage(UCanvas* Canvas, FNWUIElement& E, const FBox2f& Rect, float Alpha, float UIScale, const FBox2f& Clip);
	void DrawText(UCanvas* Canvas, FNWUIElement& E, const FBox2f& Rect, float Alpha, float UIScale, const FBox2f& Clip);
	UFont* TextFont(const FNWUIElement& E) const;
	float TextScale(UCanvas* Canvas, const FNWUIElement& E, UFont* Font, float UIScale) const;

	TArray<FNWUICanvasLayout> Canvases;
};
